import { JsonObject, TokenStatus, QuotaPoolStatus, LocalComputeStatus, QuotaSource, UsageConfidence } from "./types";
import { AgyQuotaClient } from "./AgyQuotaClient";
import matter from "gray-matter";

const QUOTA_CACHE_TTL_MS = 60_000;
const MAX_SESSION_SCAN_DEPTH = 5;
const MAX_SESSION_FILES = 80;
const MAX_SESSION_FILE_BYTES = 256 * 1024;
const MAX_SESSION_LINES_PER_FILE = 1_000;
