  private async fetchGpuMetrics(): Promise<{ utilization: number; usedMb: number; totalMb: number } | undefined> {
    try {
      const output = await this.execFileText(
        "nvidia-smi",
        ["--query-gpu=utilization.gpu,memory.used,memory.total", "--format=csv,noheader,nounits"],
        { timeoutMs: 5_000 },
      );
      const rows = output
        .split(/\r?\n/)
        .map((line) => line.trim())
        .filter(Boolean)
        .map((line) => line.split(",").map((part) => Number.parseFloat(part.trim())))
        .filter((parts) => parts.length >= 3 && parts.every((part) => Number.isFinite(part)));

      if (rows.length === 0) {
        return undefined;
      }

      const totals = rows.reduce(
        (acc, [utilization, usedMb, totalMb]) => ({
          utilization: acc.utilization + utilization,
          usedMb: acc.usedMb + usedMb,
          totalMb: acc.totalMb + totalMb,
        }),
        { utilization: 0, usedMb: 0, totalMb: 0 },
      );

      return {
        utilization: Math.round(totals.utilization / rows.length),
        usedMb: Math.round(totals.usedMb),
        totalMb: Math.round(totals.totalMb),
      };
    } catch {
      return undefined;
    }
  }

  // Collector for Local LLM
  private async fetchLocalLlmStatus(): Promise<{ localComputeStatus: LocalComputeStatus; quotaPool?: QuotaPoolStatus }> {
    const gpuMetrics = await this.fetchGpuMetrics();
    const withGpuMetrics = (status: LocalComputeStatus): LocalComputeStatus => ({
      ...status,
      vramUsedMb: gpuMetrics?.usedMb,
      vramTotalMb: gpuMetrics?.totalMb,
      gpuUtilizationPercentage: gpuMetrics?.utilization,
    });

    const probes: Array<{
      programName: string;
      quotaPoolId: string;
      url: string;
      modelsFromJson: (parsed: JsonObject) => string[];
    }> = [
      {
        programName: "Ollama",
        quotaPoolId: "local.ollama",
        url: "http://localhost:11434/api/ps",
        modelsFromJson: (parsed) => {
          const models = Array.isArray(parsed.models) ? parsed.models : [];
          return models.map((model: any) => String(model?.name || "")).filter(Boolean);
        },
      },
      {
        programName: "LM Studio",
        quotaPoolId: "local.lm-studio",
        url: "http://localhost:1234/v1/models",
        modelsFromJson: (parsed) => {
          const models = Array.isArray(parsed.data) ? parsed.data : [];
          return models.map((model: any) => String(model?.id || "")).filter(Boolean);
        },
      },
      {
        programName: "vLLM",
        quotaPoolId: "local.vllm",
        url: "http://localhost:8000/v1/models",
        modelsFromJson: (parsed) => {
          const models = Array.isArray(parsed.data) ? parsed.data : [];
          return models.map((model: any) => String(model?.id || "")).filter(Boolean);
        },
      },
    ];

    for (const probe of probes) {
      try {
        const response = await this.execFileText("curl", ["-s", "--max-time", "2", probe.url], { timeoutMs: 3_000 });
        const parsed = JSON.parse(response) as JsonObject;
        const loadedModels = probe.modelsFromJson(parsed);

        return {
          localComputeStatus: withGpuMetrics({
            endpointHealth: "ok",
            programName: probe.programName,
            loadedModels,
          }),
          quotaPool: {
            id: probe.quotaPoolId,
            provider: "local",
            source: "local-service",
            confidence: "exact",
          },
        };
      } catch {
        // Continue probing the next common local LLM endpoint.
      }
    }

    return {
      localComputeStatus: withGpuMetrics({
        endpointHealth: "offline",
        loadedModels: [],
      }),
    };
  }

